def split_cents(total, n):
    """Split a cent total into n integer parts that sum exactly to total."""
    if n <= 0:
        raise ValueError("n must be a positive integer")

    base = total // n
    remainder = total % n

    # Distribute the leftover cents one-by-one to keep integer parts.
    return [base + 1] * remainder + [base] * (n - remainder)
